// returns {size, min, max, isBST}
vector<int> fold(TreeNode* r, int& best){
    if (!r) return {0, INT_MAX, INT_MIN, 1};
    auto L = fold(r->left, best);
    auto R = fold(r->right, best);
    if (L[3] && R[3] && r->val > L[2] && r->val < R[1]) {
        int sz = L[0] + R[0] + 1;
        best = max(best, sz);
        return {sz, min(L[1], r->val), max(R[2], r->val), 1};
    }
    return {max(L[0], R[0]), 0, 0, 0};   // poison upward
}

TreeNode* prevAcc = nullptr; // store NODE, add its val lazily OR carry int sum
int run = 0;
void rev(TreeNode* r){
    if(!r) return;
    rev(r->right);            // largest first
    run += r->val;
    r->val = run;             // replace with suffix sum
    rev(r->left);
}
